<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:10px}h1{text-align:center}table{width:100%;border-collapse:collapse;margin:8px 0}th,td{border:1px solid #777;padding:5px}.signatures td{border:0;text-align:center;padding-top:50px}</style></head><body><h1>ACTA DE REUNIÓN — {{$minute->meeting->committee->name}}</h1><p><b>Empresa:</b> {{$minute->meeting->committee->company->razon_social}} · <b>NIT:</b> {{$minute->meeting->committee->company->nit}}</p><p><b>Acta:</b> {{$minute->minute_number}} · <b>Tipo:</b> {{$minute->meeting->meeting_type}} · <b>Fecha:</b> {{$minute->meeting->meeting_date->format('d/m/Y')}} · <b>Hora:</b> {{$minute->meeting->start_time}} — {{$minute->meeting->end_time}}</p><p><b>Lugar/modalidad:</b> {{$minute->meeting->location}} / {{$minute->meeting->modality}} · <b>Presidente:</b> {{$minute->meeting->president->employee->nombre_completo}} · <b>Secretario:</b> {{$minute->meeting->secretary->employee->nombre_completo}}</p><h3>Asistencia y quórum</h3><p>Presentes válidos: {{$minute->meeting->quorum_present}} · Requerido: {{$minute->meeting->quorum_required}} · {{$minute->meeting->has_quorum?'Con quórum':'Sin quórum'}}</p><table><tr><th>Integrante</th><th>Estado</th></tr>@foreach($minute->meeting->attendees as $a)<tr><td>{{$a->member?->employee?->nombre_completo?:$a->external_name}}</td><td>{{$a->attendance_status}}</td></tr>@endforeach</table><h3>Orden del día y desarrollo</h3>@foreach($minute->meeting->agendaItems as $item)<h4>{{$item->sort_order}}. {{$item->title}}</h4><p>{{$item->development}}</p><p><b>Conclusión:</b> {{$item->conclusions}}</p>@endforeach<h3>Decisiones</h3>@foreach($minute->meeting->decisions as $d)<p>{{$d->description}} — {{$d->approved?'Aprobada':'No aprobada'}}</p>@endforeach<h3>Compromisos</h3><table><tr><th>Descripción</th><th>Responsable</th><th>Fecha límite</th></tr>@foreach($minute->meeting->commitments as $c)<tr><td>{{$c->description}}</td><td>{{$c->responsible->nombre_completo}}</td><td>{{$c->due_date->format('d/m/Y')}}</td></tr>@endforeach</table><table class="signatures"><tr><td>____________________<br>Presidente</td><td>____________________<br>Secretario</td></tr></table></body></html>
